class Hesap {
    protected double bakiye;
    void paraCek(double tutar) {
        if (tutar > bakiye) throw new IllegalArgumentException("Yetersiz bakiye");
        bakiye -= tutar;
    }
}

class KilitliHesap extends Hesap {
    @Override
    void paraCek(double tutar) {
        throw new UnsupportedOperationException("Kilitli hesaptan para çekilemez");
    }
}

class GunSonuIslemleri {
    void ucretTahsilEt(java.util.List<Hesap> hesaplar, double ucret) {
        for (Hesap h : hesaplar) {
            h.paraCek(ucret);
        }
    }
}

