        wait(NULL);
        printf("ebeveyn %d\n", x);
    }
    return 0;
}

int islemUcreti(int tutar, boolean vip, int deneme) {
    int ucret = 0;
    if (tutar > 10000) {
        ucret = 50;
    } else if (tutar > 1000) {
        ucret = 10;
    }
    if (vip) {
        ucret = 0;
    }
    while (deneme > 0) {
        deneme--;
    }
    return ucret;
}

int krediPuani(int gelir, boolean kefil) {
    int puan = 0;
    if (gelir > 5000) {
        puan += 10;
    }
    if (kefil) {
        puan += 5;
    }
    return puan;
}

